import pathlib,json,hashlib,math,sqlite3,shapely
from shapely.geometry import Polygon,box,mapping
from shapely.ops import transform,polylabel
B=pathlib.Path('data/model-source/bespoke');P=B/'acro-riverview-101-representative';P.mkdir(exist_ok=True);Q=B/'acro-riverview-research';src=Q/'root-reviewed-source-101-105.json';sh=hashlib.sha256(src.read_bytes()).hexdigest();assert sh=='1d0a4f420d72a16bf5c82e4e8aeede8ab56930be7882809eb324fdb3a776f7aa';photo=Q/'images/daangn-riverview-1-original.jpeg';ph=hashlib.sha256(photo.read_bytes()).hexdigest();assert ph=='16ab5a8f40bc47498ba8149cb75d33371bfe42f924af4fcfcdc99ae1b6e0b86f';A=json.loads(src.read_text());e=next(x for x in A['entries'] if x['tower']=='101동');b=e['osm_building'];db=sqlite3.connect('data/model-source/residential-survey/register.sqlite');db.row_factory=sqlite3.Row;reg=dict(db.execute('select * from reg where id=?',(e['register']['id'],)).fetchone());assert reg==e['register'] and float(reg['height'])==93.55 and int(reg['floors'])==31;g=json.loads(b['geometry']);outer=g['coordinates'][0][:-1];lon=sum(x for x,y in outer)/len(outer);lat=sum(y for x,y in outer)/len(outer);rings=[[[ (x-lon)*111320*math.cos(math.radians(lat)),(y-lat)*111320] for x,y in r[:-1]] for r in g['coordinates']];r=rings[0];poly=Polygon(r,rings[1:]);a,z=max(zip(r,r[1:]+r[:1]),key=lambda q:math.dist(*q));theta=math.atan2(z[1]-a[1],z[0]-a[0]);co,si=math.cos(theta),math.sin(theta);uv=transform(lambda x,y:(x*co+y*si,-x*si+y*co),poly);c=polylabel(uv,tolerance=.01);w,h=10.,5.
while not uv.buffer(-.25).covers(box(c.x-w/2-.2,c.y-h/2-.2,c.x+w/2+.2,c.y+h/2+.2)):w*=.95;h*=.95
D={'tower':'101','approved_entry':e,'id':b['id'],'geometry':g,'ring_m':r,'rings_m':rings,'anchor_lonlat':[lon,lat],'register_row':reg,'register_height_m':93.55,'floors':31,'osm_height_m':b['height_m'],'facade_axis_rad_inferred':theta,'roof_cap_uv':[c.x,c.y,w,h],'body_height_m':92.30,'roof_deck_height_m':92.55,'model_upper_envelope_m':93.55,'reference_scope':'Complex-photo-inference from listing card photo; not a resident review. Numbered tower and compass orientation unconfirmed.','height_assumption':'No source child parts; own full concave footprint modeled with uniform registered maximum93.55m. Modest flat cap geometry inferred; legal roof datum unconfirmed.','source_sha256':sh,'photo_sha256':ph,'photo_review':json.loads((Q/'root-photo-review.json').read_text()),'supersedesAssetIds':None,'proposedSupersedesAssetIds':['fallback-acro-riverview-101'],'binding_status':'pending root verified fallback split','current_owner_asset_ids':[],'inferredFromAssetIds':[]};(P/'source-data.json').write_text(json.dumps(D,ensure_ascii=False,indent=2));(P/'regions.json').write_text(json.dumps([{'id':'uniform-parent-assumption','geometry':mapping(poly),'height_m':93.55,'roof_deck_height_m':92.55,'body_height_m':92.30,'floors':31,'basis':D['height_assumption'],'triangles':[list(q.exterior.coords)[:3] for q in shapely.constrained_delaunay_triangles(poly).geoms]}],indent=2));(P/'source-provenance.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [src,photo,Q/'root-photo-review.json']},indent=2));(P/'prior-hashes.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Q.rglob('*') if p.is_file()},indent=2));print('own source',b['id'],'roof cap',D['roof_cap_uv'])
